INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 42 anos submetido a mastectomia radical com linfadenectomia axilar queixa-se no pós-operatório de dormência e queimação na face interna do braço ipsilateral. Qual o nervo sensitivo provavelmente lesionado ou manipulado?", "options": {"a": "Nervo Torácico Longo.", "b": "Nervo Toracodorsal.", "c": "Nervo Intercostobraquial.", "d": "Nervo Mediano.", "e": "Nervo Musculocutâneo."}, "answer": "c", "rationale": "O nervo intercostobraquial atravessa a axila e fornece sensibilidade à face interna do braço. Sua lesão é uma complicação sensorial comum em esvaziamentos axilares.", "option_rationales": {"a": "Incorreta. Sua lesão causaria ''escápula alada'' (motor).", "b": "Incorreta. Inerva o grande dorsal (motor).", "c": "Correta. Nervo puramente sensitivo manipulado na linfadenectomia axilar.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Mastologia", "Pós-operatório", "Linfadenectomiaaxilar", "Lesão Nervosa"]}', 131, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma cirurgia de tireoide, o paciente apresenta dormência perioral e sinal de Chvostek positivo (contração da musculatura facial ao percutir o nervo facial). Qual a conduta imediata mais adequada?", "options": {"a": "Apenas observar e repetir exame em 24h.", "b": "Solicitar Cálcio Iônico e considerar reposição de Gluconato de Cálcio venoso se sintomas persistirem.", "c": "Realizar traqueostomia.", "d": "Dar alta hospitalar.", "e": "Prescrever apenas Vitamina D isolada."}, "answer": "b", "rationale": "Sinais de hipocalcemia (parestesias, Chvostek, Trousseau) exigem avaliação laboratorial imediata e reposição para evitar convulsões ou laringoespasmo (emergência).", "option_rationales": {"a": "Incorreta. Hipocalcemia sintomática pode progredir para óbito.", "b": "Correta. Manejo padrão de hipoparatiroidismo pós-operatório.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Vitamina D demora dias para agir."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Hipocalcemia", "Manejo"]}', 132, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''íleo paralítico'' é comum após cirurgias abdominais. No entanto, se a distensão de cólon for massiva (> 10-12 cm no ceco) sem evidência de obstrução mecânica em um paciente grave, o diagnóstico provável é:", "options": {"a": "Sindrome de Ogilvie (Pseudo-obstrução colônica aguda).", "b": "Volvulo de sigmoide.", "c": "Intussusceção.", "d": "Hérnia estrangulada.", "e": "Perfuração por câncer."}, "answer": "a", "rationale": "A Síndrome de Ogilvie é a dilatação aguda do cólon sem causa mecânica, ocorrendo em pacientes com graves distúrbios metabólicos ou pós-operatórios de grandes cirurgias extraterritoriais (ex: quadril, coração).", "option_rationales": {"a": "Correta. Diagnóstico clínico-radiográfico específico.", "b": "Incorreta. É causa mecânica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Ogilvie", "Pseudo-obstrução"]}', 133, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''parada respiratória'' súbita em um paciente na sala de recuperação pós-anestésica (SRPA) que acabou de receber altas doses de opioides para controle de dor intensa?", "options": {"a": "Choque anafilático.", "b": "Depressão respiratória central induzida por opioides.", "c": "Atelectasia maciça.", "d": "Tromboembolismo pulmonar.", "e": "Pneumotórax espontâneo."}, "answer": "b", "rationale": "Os opioides aguem nos receptores mu do tronco cerebral, reduzindo a sensibilidade ao CO2 e podendo causar apneia. O tratamento imediato é ventilação sob máscara e Naloxona.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Principal complicação grave dos opioides em altas doses.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Opioides", "Complicações"]}', 134, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a ressecção gástrica em Y-de-Roux apresenta, logo após a alimentação, sintomas de palpitação, sudorese, náuseas e diarreia, seguidos de hipoglicemia reacional 2 horas depois. Este quadro é conhecido como:", "options": {"a": "Sindrome do Intestino Curto.", "b": "Sindrome de Dumping (Precoce e Tardio).", "c": "Sindrome da Alça Cega.", "d": "Gastrite de refluxo alcalino.", "e": "Esofagite de Barrett."}, "answer": "b", "rationale": "O Dumping ocorre pela perda do piloro, levando à passagem rápida de conteúdo osmótico para o intestino delgado, causando expansão volêmica intestinal (precoce) e pico de insulina (tardio).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Síndrome disabsortiva e motora típica de pós-gastrectomias.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia do Aparelho Digestivo", "Pós-operatório", "Dumping", "Gastrectomia"]}', 135, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''quilotórax'' após esofagectomia pode ser tratada inicialmente de forma conservadora. Qual a base dietética deste tratamento para reduzir o débito de quilo?", "options": {"a": "Dieta rica em gorduras animais.", "b": "Dieta zero ou dieta com Triglicerídeos de Cadeia Média (TCM), que são absorvidos diretamente pela veia porta sem passar pelos linfáticos.", "c": "Dieta rica em fibras.", "d": "Uso de apenas líquidos clarificados.", "e": "Mistura de óleos vegetais."}, "answer": "b", "rationale": "O quilo é formado a partir de gorduras de cadeia longa. O uso de TCM reduz a produção de quilo e permite que a fístula linfática feche espontaneamente em muitos casos.", "option_rationales": {"a": "Incorreta. Pioraria muito o débito.", "b": "Correta. Manejo nutricional específico para fístulas linfáticas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Torácica", "Pós-operatório", "Quilotórax", "Nutrição"]}', 136, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 75 anos, no 4º DPO de uma cirurgia de quadril, apresenta subitamente dor abdominal difusa e parada de eliminação de gazes. O Raio-x mostra dilatação de todo o cólon até o sigmoide, sem níveis hidroaéreos sugestivos de obstrução delgada. Qual o tratamento farmacológico de escolha para a síndrome de Ogilvie se não houver melhora com medidas iniciais?", "options": {"a": "Furosemida.", "b": "Neostigmina (inibidor da acetilcolinesterase).", "c": "Morfina.", "d": "Atropina.", "e": "Antibióticos de largo espectro."}, "answer": "b", "rationale": "A neostigmina estimula o sistema parassimpático, promovendo o peristaltismo colônico. Deve ser usada sob monitorização cardíaca devido ao risco de bradicardia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Droga de escolha no Ogilvie refratário.", "c": "Incorreta. Opioides pioram o íleo.", "d": "Incorreta. Anticolinérgicos pioram o íleo.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Sindrome de Ogilvie", "Tratamento"]}', 137, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual dos fatores abaixo é considerado o mais importante fator de risco MODIFICÁVEL para o desenvolvimento de Infecção de Sítio Cirúrgico (ISC) no período perioperatório?", "options": {"a": "Idade avançada.", "b": "Sexo masculino.", "c": "Tabagismo.", "d": "Controle glicêmico inadequado (Hiperglicemia perioperatória).", "e": "Tipo de fio de sutura (Seda vs Nylon)."}, "answer": "d", "rationale": "A hiperglicemia perioperatória (mesmo em não diabéticos) está fortemente associada a piores desfechos infecciosos. O controle rigoroso da glicemia reduz a incidência de ISC.", "option_rationales": {"a": "Incorreta. Não é modificável.", "b": "Incorreta. Não é modificável.", "c": "Incorreta. É modificável, mas o controle glicêmico agudo tem impacto mais imediato na resposta imune local.", "d": "Correta. Fator de risco crítico e manejável.", "e": "Incorreta. Embora o monofilamento seja melhor, não supera o controle glicêmico."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Prevenção"]}', 138, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a cirurgias de próstata ou bexiga, qual o sinal clínico clássico de uma fístula urinária para o abdome após a cirurgia?", "options": {"a": "Aumento súbito da ureia e creatinina sérica mimetizando insuficiência renal por reabsorção peritoneal de urina (Dialise pseudorrenal).", "b": "Febre alta e choque séptico imediato.", "c": "Vômitos biliosos.", "d": "Hematúria persistente silenciosa.", "e": "Icterícia tardia."}, "answer": "a", "rationale": "A urina na cavidade peritoneal tem seus componentes (ureia/creatina) reabsorvidos pela membrana peritoneal, elevando os níveis séricos antes mesmo de haver sinais claros de ascite ou peritonite urinária.", "option_rationales": {"a": "Correta. Fenômeno de reabsorção que confunde o diagnóstico inicial.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Urologia", "Pós-operatório", "Fístula Urinária", "Insuficiência Renal"]}', 139, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "O ''Seroma'' é uma coleção de líquido linfático e soro no subcutâneo da ferida. Qual cirurgia abaixo apresenta a maior incidência desta complicação devido à grande área de descolamento de tecidos?", "options": {"a": "Apendicectomia laparoscópica.", "b": "Mastectomia radical e Abdominoplastia.", "c": "Herniorrafia inguinal.", "d": "Tireoidectomia.", "e": "Cirurgia de túnel do carpo."}, "answer": "b", "rationale": "A criação de grandes espaços mortos facilita o acúmulo de líquido linfático. Mastectomias e cirurgias plásticas abdominais são campeãs em formação de seromas.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Cirurgias com grande descolamento tecidual.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Seroma", "Epidemiologia"]}', 140, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica extensa recebe Nutrição Parenteral Total (NPT) por veia central. No 4º dia, desenvolve febre de 39°C e fungemia (Cândida no sangue). Qual a conduta prioritária além da antifungicoterapia?", "options": {"a": "Manter o acesso central a todo custo.", "b": "Retirada imediata do cateter venoso central suspeito.", "c": "Dobrar a dose da NPT.", "d": "Realizar laparotomia exploradora.", "e": "Trocar apenas o filtro da NPT."}, "answer": "b", "rationale": "A IPCS por fungos é indicação absoluta de retirada do cateter central, pois os fungos colonizam o cateter formando biofilmes resistentes.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta padrão em IPCS fúngica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "NPT", "IPCS"]}', 141, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma neurocirurgia complexa, o paciente apresenta hiponatremia severa (Sódio de 125 mEq/L) mas com volume intravascular NORMAL (euvolemia) e urina concentrada. Qual o diagnóstico mais provável?", "options": {"a": "Diabetes Insipidus.", "b": "SIADH (Síndrome da Secreção Inapropriada de ADH).", "c": "Cerebral Salt Wasting (Perda cerebral de sal).", "d": "Intoxicação hídrica por soro glicosado.", "e": "Choque Séptico."}, "answer": "b", "rationale": "A SIADH após trauma/cirurgia craniana leva à retenção excessiva de água livre, diluindo o sódio plasmático em um paciente que não apresenta sinais de desidratação ou edema.", "option_rationales": {"a": "Incorreta. Causaria hipernatremia.", "b": "Correta. Quadro clínico de hiponatremia euvolêmica.", "c": "Incorreta. Cerebral Salt Wasting cursa com hipovolemia (desidratação).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Neurocirurgia", "Pós-operatório", "SIADH", "Hiponatremia"]}', 142, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''hemorragia digestiva alta'' (úlcera de Cushing) em pacientes submetidos a neurocirurgias ou com trauma cranioencefálico grave?", "options": {"a": "Uso de corticoides no pós-operatório.", "b": "Hipersecreção ácida gástrica secundária à estimulação do nervo vago por aumento da pressão intracraniana.", "c": "Álcool usado na assepsia.", "d": "Cirrose hepática desconhecida.", "e": "Helicobacter pylori."}, "answer": "b", "rationale": "A fisiopatologia da Úlcera de Cushing envolve a estimulação vagal central devido à hipertensão intracraniana, resultando em hipersecreção de ácido clorídrico.", "option_rationales": {"a": "Incorreta. Corticoides podem prejudicar a cicatrização da úlcera, mas não são o mecanismo primário da úlcera de Cushing.", "b": "Correta. Mecanismo fisiopatológico bem estabelecido no trauma/neurocirurgia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "Úlcera de Cushing", "HDA"]}', 143, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente idoso, no 5º DPO de uma cirurgia de ressecção de tumor de cólon, apresenta abaulamento e dor em região da glândula parótida direita, com saída de pus pelo ducto de Stenon à ordenha da glândula. Qual a causa provável e o fator de risco associado?", "options": {"a": "Sarcoidose.", "b": "Parotidite aguda bacteriana; desidratação e higiene oral precária.", "c": "Linfoma parotídeo.", "d": "Sindrome de Sjogren exacerbada.", "e": "Obstrução litiásica crônica."}, "answer": "b", "rationale": "A parotidite supurativa é uma complicação de pacientes cirúrgicos debilitados e desidratados. A falta de estímulo salivar pelo jejum e a desidratação facilitam a ascensão de bactérias da boca pela glândula.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Evolução clássica em pacientes idosos no pós-op abdominal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Parotidite", "Complicações"]}', 144, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes obesos mórbidos, a deficiência nutricional mais comum após a cirurgia bariátrica disabsortiva (Y-de-Roux ou Derivação Biliopancreática) que causa anemia microcítica e hipocrômica é:", "options": {"a": "Deficiência de Ferro.", "b": "Deficiência de Vitamina B12.", "c": "Deficiência de Ácido Fólico.", "d": "Deficiência de Cobre.", "e": "Deficiência de Cálcio."}, "answer": "a", "rationale": "Embora a B12 seja muito importante, a deficiência de ferro é extremamente frequente devido ao bypass do duodeno e à redução da acidez gástrica necessária para a conversão do ferro férrico em ferroso.", "option_rationales": {"a": "Correta. Principal causa de anemia pós-bariátrica.", "b": "Incorreta. B12 causa anemia macrocítica.", "c": "Incorreta. Macrocítica.", "d": "Incorreta. Rara.", "e": "Incorreta. Não causa anemia."}, "difficulty": "facil", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Anemia", "Nutrição"]}', 145, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma cirurgia torácica, o dreno de tórax apresenta uma drenagem de 100 ml de sangue escuro. O médico nota bolhas subindo no frasco selado à água toda vez que o paciente tosse. Qual o significado deste achado?", "options": {"a": "O dreno está obstruído.", "b": "Presença de fístula aérea (escape de ar do pulmão para a pleura).", "c": "Hemotórax maciço iminente.", "d": "Infeccção pelo dreno.", "e": "O dreno está na posição errada (dentro do estômago)."}, "answer": "b", "rationale": "O borbulhamento (fuga aérea) no sistema de drenagem de tórax indica que ainda há ar sendo liberado do parênquima pulmonar ou da árvore brônquica.", "option_rationales": {"a": "Incorreta. Se estivesse obstruído, não veríamos bolhas.", "b": "Correta. Sinais de escape aéreo.", "c": "Incorreta. 100 ml de sangue escuro é normal no pós-op torácico.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Torácica", "Pós-operatório", "Dreno de Tórax", "Fuga Aérea"]}', 146, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação metabólica temida na síndrome de realimentação (Refeeding Syndrome) em pacientes cronicamente desnutridos que começam a receber aporte calórico agressivo?", "options": {"a": "Hipermagnesemia.", "b": "Hipofosfatemia severa.", "c": "Hipernatremia.", "d": "Acidose lática persistente.", "e": "Bradicardia intensa."}, "answer": "b", "rationale": "A introdução de carboidratos leva a um pico de insulina, que empurra o fósforo (potássio e magnésio) para dentro das células para a produção de ATP, resultando em níveis séricos perigosamente baixos de fósforo.", "option_rationales": {"a": "Incorreta. Magnésio também cai.", "b": "Correta. Marcador clássico da síndrome de realimentação.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Pode causar insuficiência cardíaca e taquicardia por edema."}, "difficulty": "media", "tags": ["Nutrologia", "Pós-operatório", "Refeeding", "Hipofosfatemia"]}', 147, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''anemia megablástica'' (macrocítica) em pacientes submetidos a gastrectomia total, que se manifesta após 3 a 5 anos da cirurgia se não houver reposição, é:", "options": {"a": "Falta de ácido clorídrico.", "b": "Falha na produção de fator intrínseco e consequente má absorção de Vitamina B12.", "c": "Perda de sangue crônica.", "d": "Intoxicação por metais pesados.", "e": "Hipotiroidismo pós-cirúrgico."}, "answer": "b", "rationale": "As células parietais do estômago produzem fator intrínseco, necessário para a absorção da B12 no íleo terminal. Sem o estômago, o estoque corporal de B12 (que dura anos) se esgota.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia da anemia perniciosa adquirida pós-gastrectomia.", "c": "Incorreta. Ferro daria anemia microcítica.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia do Aparelho Digestivo", "Pós-operatório", "Vitamina B12", "Gastrectomia"]}', 148, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve eritema, calor e edema em face lateral da coxa, com saída de bolhas de gás pela ferida operatória no 1º DPO. O quadro é de progressão rapidíssima e o paciente está em choque. Qual o agente etiológico mais comum para esta Gangrena Gasosa?", "options": {"a": "Streptococcus pyogenes.", "b": "Clostridium perfringens.", "c": "Escherichia coli.", "d": "Bacteroides fragilis.", "e": "Staphylococcus epidermidis."}, "answer": "b", "rationale": "Clostridium perfringens é um anaeróbio formador de esporos que produz potentes toxinas causadoras de mionecrose e produção de gás nos tecidos.", "option_rationales": {"a": "Incorreta. Causa fascina necrotizante ''a carne comendo'', mas não costuma produzir tanto gás.", "b": "Correta. Agente clássico da mionecrose clostridiana.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Infectologia", "Pós-operatório", "Gangrena Gasosa", "Clostridium"]}', 149, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma parotidectomia profunda, qual a complicação neurológica motora mais temida e testada ao pedir para o paciente sorrir ou fechar os olhos?", "options": {"a": "Paralisia do Nervo Trigêmeo.", "b": "Lesão do Nervo Facial (VII par).", "c": "Lesão do Nervo Glossofaríngeo.", "d": "Paralisia de pregas vocais.", "e": "Síndrome de Horner."}, "answer": "b", "rationale": "O nervo facial atravessa o parênquima da parótida, dividindo os lobos superficial e profundo. Sua manipulação ou lesão causa paralisia da musculatura da mímica facial.", "option_rationales": {"a": "Incorreta. Sensibilidade da face.", "b": "Correta. Risco anatômico principal na cirurgia de parótida.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Facial", "Parotidectomia"]}', 150, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o achado gasométrico inicial esperado em um paciente com Embolia Pulmonar aguda, antes da instalação de fadiga respiratória ou choque?", "options": {"a": "Acidose respiratória com hipercapnia.", "b": "Alcalose respiratória com hipocapnia (pCO2 baixa) e hipoxemia.", "c": "Acidose metabólica por lactato.", "d": "Alcalose metabólica.", "e": "Gap aniônico elevado sem acidose."}, "answer": "b", "rationale": "A dor e o drive respiratório aumentado pela hipoxemia levam à hiperventilação compensatória, ''lavando'' o CO2 e gerando alcalose respiratória.", "option_rationales": {"a": "Incorreta. Ocorre apenas em fases terminais de falência pulmonar.", "b": "Correta. Padrão gasométrico clássico do TEP inicial.", "c": "Incorreta. Ocorre se houver choque obstrutivo grave associado.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Pós-operatório", "TEP", "Gasometria"]}', 151, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a esplenectomia de urgência por trauma abdominal apresenta, no 3º DPO, febre de 38°C e drenagem de líquido amarelado pelo dreno localizado no leito esplênico com amilase de 5.000 U/L. Qual a complicação?", "options": {"a": "Pneumonia basal.", "b": "Fístula da cauda do pâncreas.", "c": "Abcesso subfrênico.", "d": "Hemoperitônio residual.", "e": "Fístula gástrica."}, "answer": "b", "rationale": "A proximidade da cauda do pâncreas com o hilo esplênico predispõe a lesões pancreáticas durante a esplenectomia, resultando em fístulas com alta concentração de amilase.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação anatômica comum pela proximidade dos órgãos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Esplenectomia", "Pâncreas"]}', 152, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma revascularização miocárdica, o paciente apresenta agitação psicomotora e tenta arrancar os acessos venosos. O quadro inicia-se à noite e melhora pela manhã. Qual o manejo inicial recomendado antes de qualquer sedação?", "options": {"a": "Internação em quarto escuro e isolamento.", "b": "Promoção de ciclo sono-vigília, luz natural durante o dia, presença de acompanhante familiar e correção de distúrbios de base.", "c": "Uso de contenção mecânica apenas.", "d": "Administração de benzodiazepínicos em bólus repetidos.", "e": "Transferência imediata para psiquiatria."}, "answer": "b", "rationale": "O tratamento do delirium começa com medidas não farmacológicas para reorientar o paciente. Benzodiazepínicos devem ser evitados, pois podem piorar o delirium no idoso (efeito paradoxal).", "option_rationales": {"a": "Incorreta. Piora a desorientação.", "b": "Correta. Manejo do Delirium foco em prevenção e reorientação.", "c": "Incorreta. Aumenta a agitação e risco de lesão.", "d": "Incorreta. Fármacos de escolha seriam antipsicóticos em baixas doses se necessário.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Delirium", "Manejo"]}', 153, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação de ferida operatória conhecida como ''Gossypiboma'' ou ''Textiloma'' refere-se a:", "options": {"a": "Infecção por fungos da ferida.", "b": "Corpo estranho retido (geralmente gaze ou compressa cirúrgica) deixado na cavidade ou na ferida.", "c": "Um tipo de câncer de pele cicatricial.", "d": "Reação alérgica ao iodo.", "e": "Hematoma calcificado."}, "answer": "b", "rationale": "Retenção de compressas é um evento adverso grave catalogado pela segurança do paciente, gerando complicações inflamatórias ou obstrutivas tardias.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição correta do termo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Corpo Estranho", "Segurança"]}', 154, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes tabagistas, a complicação de cicatrização de ferida operatória é mediada principalmente por qual mecanismo fisiopatológico causado pela nicotina?", "options": {"a": "Vasodilatação excessiva.", "b": "Vasoconstrição periférica e redução da oxigenação tecidual (hipóxia local).", "c": "Aumento da proliferação de fibroblastos.", "d": "Melhora da síntese de colágeno.", "e": "Inibição do crescimento bacteriano."}, "answer": "b", "rationale": "A nicotina causa vasoconstrição e aumenta a agregação plaquetária, reduzindo o aporte de O2 necessário para o metabolismo oxidativo da cicatrização e para os macrófagos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo central da má cicatrização do fumante.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Tabagismo", "Cicatrização"]}', 155, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetida a colecistectomia videolaparoscópica de urgência evolui no 3º DPO com dor abdominal e icterícia (Bilirrubina Total de 6.0 mg/dL, com Direta de 4.8 mg/dL). Ultrassom mostra líquido livre e vias biliares intra-hepáticas dilatadas. Qual o diagnóstico?", "options": {"a": "Hepatite medicamentosa por anestésicos.", "b": "Lesão iatrogênica da via biliar principal (ligadura ou clipagem inadvertida do colédoco).", "c": "Gastrite erosiva.", "d": "Síndrome de Mirizzi crônica.", "e": "Coledocolitíase residual oculta."}, "answer": "b", "rationale": "A combinação de dor, icterícia obstrutiva e dilatação biliar precoce após colecistectomia sugere obstrução traumática da via biliar.", "option_rationales": {"a": "Incorreta. Não dilataria a via biliar no USG.", "b": "Correta. Complicação temida da colecistectomia laparoscópica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Embora possível, a lesão cirúrgica é a hipótese prioritária num quadro abrupto pós-op."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Lesão Biliar", "Complicações"]}', 156, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta inicial diante de uma deiscência de ferida operatória abdominal em ambiente de enfermaria, onde observa-se a protrusão de alças de intestino delgado através da ferida (Evisceração)?", "options": {"a": "Tentar empurrar o intestino para dentro imediatamente no quarto do paciente.", "b": "Cobrir as alças com compressas estéreis embebidas em soro fisiológico morno e encaminhar o paciente imediatamente ao centro cirúrgico.", "c": "Dar água para o paciente beber para acalmar.", "d": "Aguardar o cirurgião titular chegar no dia seguinte.", "e": "Aplicar antisséptico iodo-povidona diretamente no intestino."}, "answer": "b", "rationale": "A evisceração é uma emergência. Deve-se proteger o órgão eviscerado de ressecamento e lesão externa até a correção cirúrgica definitiva.", "option_rationales": {"a": "Incorreta. Risco de perfuração e infecção maciça.", "b": "Correta. Conduta de emergência padrão.", "c": "Incorreta. Preparar para cirurgia (jejum).", "d": "Incorreta.", "e": "Incorreta. PVPI pode ser agressivo para a serosa intestinal."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Evisceração", "Manejo Emergencial"]}', 157, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A Síndrome da Angústia Respiratória Aguda (SARA/SDRA) pode ocorrer no pós-operatório como parte de uma resposta inflamatória sistêmica (SIRS) ou sepse. Qual o achado radiológico característico no Raio-x de tórax?", "options": {"a": "Coração em gota.", "b": "Infiltrado alveolar bilateral difuso em ''asa de borboleta'', sem sinais óbvios de cardiomegalia/congestão cardíaca primária.", "c": "Hiperluzência focal unilateral.", "d": "Atelectasia lobar pura.", "e": "Derrame pleural isolado."}, "answer": "b", "rationale": "A SDRA é um edema pulmonar não cardiogênico. O infiltrado bilateral é o critério radiológico fundamental.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Descrição clássica da imagem da SDRA.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "SDRA", "Pneumologia"]}', 158, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de reto apresenta no 7º DPO saída de ar e fezes pela vagina (Fístula Retovaginal). Qual a causa técnica provável desta fístula em cirurgias com anastomose colorretal baixa?", "options": {"a": "Infecção urinária.", "b": "Lesão inadvertida da parede vaginal posterior durante a dissecção do espaço retovaginal ou inclusão da vagina no grampeamento da anastomose.", "c": "Diarreia infecciosa.", "d": "Uso de papel higiênico áspero.", "e": "Menopausa precoce."}, "answer": "b", "rationale": "A fístula retovaginal no pós-op imediato sugere trauma cirúrgico direto ou isquemia por grampeamento acidental de parte da vagina.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo de lesão técnica iatrogênica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Proctologia", "Pós-operatório", "Fístula", "Complicações"]}', 159, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia abdominal, o paciente desenvolve quadro de colite com diarreia profusa, dor abdominal e febre após o uso de antibióticos por 7 dias. O teste de toxina nas fezes é positivo para Clostridioides difficile. Qual o tratamento de primeira linha recomendado?", "options": {"a": "Loperamida (Imodium).", "b": "Vancomicina oral ou Fidaxomicina.", "c": "Amoxicilina.", "d": "Ciprofloxacino.", "e": "Dieta rica em fibras apenas."}, "answer": "b", "rationale": "A colite pseudomembranosa por C. difficile é uma complicação do uso de antibióticos. O tratamento exige antibióticos específicos que ajam no lúmen intestinal (Vancomicina oral) e suspensão do antibiótico causador se possível.", "option_rationales": {"a": "Incorreta. Contraindicado por risco de megacólon tóxico.", "b": "Correta. Tratamento de escolha atualizado.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Infectologia", "Pós-operatório", "C. difficile", "Tratamento"]}', 160, 'draft')
